function materialIcon(id){let m=MATERIALS[id],s=m&&SPECIES[m.species],tier=m?.tier||0,role=s?.role||0;let shapes=['M18 12 34 5 48 22 40 51 16 47 9 29Z','M30 5 51 29 31 55 10 29Z','M13 14 43 10 52 39 30 54 9 38Z','M30 5 49 17 54 40 30 56 7 40 12 17Z'];return '<svg viewBox="0 0 60 60" class="material-icon" aria-hidden="true" style="color:'+m.color+'"><path d="'+shapes[tier]+'"/><path d="M18 28 30 15 42 28 30 42Z"/><path style="fill-opacity:.65" d="'+['M19 17Q43 21 25 46Q31 29 19 17Z','M30 14 40 29 30 46 20 29Z','M20 43 38 16 41 19 26 44Z M17 36 31 45','M18 43 41 17 M29 18 41 17 40 29 M18 34 25 41','M18 20 30 15 42 20 39 37 30 45 21 37Z','M18 17Q26 29 18 43 M28 16Q36 29 28 45 M38 18Q46 29 38 42','M30 15Q45 16 34 29Q47 39 33 40Q27 51 25 37Q11 37 23 28Q17 15 30 15Z','M30 15Q48 32 35 43Q16 48 20 31Q29 38 30 15Z'][role%8]+'"/></svg>';}
function materialTile(id,required=0){let m=MATERIALS[id];if(!m)return '';let owned=campaign().materials[id]||0;return '<div class="material-tile '+(required>owned?'material-short':'')+'" title="'+gearEscape(m.name)+'">'+materialIcon(id)+'<div><strong>'+gearEscape(m.name)+'</strong><span>所持 × '+owned+'</span>'+(required?'<span>使用 × '+required+(owned<required?' · あと '+(required-owned):'')+'</span>':'')+'</div></div>';}
forgeCostHtml=(spec,tier,endgame=false)=>{let status=forgeAvailability(spec,tier,endgame);return '<div class="forge-material-status" role="status"><p>'+status.reason+'</p>'+status.rows.map(row=>materialTile(row.id,row.required)).join('')+'<small>鞄 '+p.bag.length+' / 20</small></div>';};
let materialRegion=0;
function showMaterials(){let c=campaign();worldMenu('素材袋','<label>地域<select aria-label="素材袋の地域" onchange="materialRegion=+this.value;showMaterials()">'+REGIONS.filter(r=>r.id<=c.unlocked).map(r=>'<option value="'+r.id+'" '+(r.id===materialRegion?'selected':'')+'>'+r.name+'</option>').join('')+'</select></label><div class="material-grid">'+Object.values(MATERIALS).filter(m=>SPECIES[m.species]?.region===materialRegion&&(c.materials[m.id]||0)>0).map(m=>materialTile(m.id)).join('')+'</div><p>素材は敵の討伐後に拾って入手します。品質は並・良・希少・伝説の4段階。</p><button onclick="showForge()">装備工房</button><button onclick="showSkillFoundry()">スキル工房</button><button onclick="showVillage()">村の依頼へ</button>','materials');}
const materialForge=showForge;showForge=(...args)=>{materialForge(...args);let info=Array.from($('card').querySelectorAll('details')).find(el=>el.querySelector('summary')?.textContent==='この敵の素材');if(info)info.innerHTML='<summary>この敵の素材</summary>'+MATERIAL_TIERS.map((_,i)=>materialTile(worldForgeSpecies+':'+i)).join('');};
// Shoulder buttons offer a reliable linear route through EVERY enabled control.
const accessibleMenuPad=padMenu;padMenu=(g,left,right,dt)=>{
 if(!inventoryNav.open&&!['inventory','gems','skills','stash'].includes(menuSurface)&&!padBinding){let step=padEdge(g,'inventory')?-1:padEdge(g,'flask')?1:0;if(step){let items=menuFocusables(),index=items.indexOf(document.activeElement);if(items.length)menuFocusElement(items[(index+step+items.length)%items.length]);return;}}
 if(menuSurface==='skillForge'&&padEdge(g,'back')&&document.activeElement?.closest?.('#foundryDetail')){menuFocusElement($('card').querySelector('[data-foundry="'+foundrySelection+'"]'));return;}
 accessibleMenuPad(g,left,right,dt);
};
const accessibleMenuMove=menuMove;menuMove=(dx,dy)=>{let el=document.activeElement;if(dx&&el?.tagName==='SELECT'){for(let i=0;i<el.options.length;i++){el.selectedIndex=(el.selectedIndex+dx+el.options.length)%el.options.length;if(!el.options[el.selectedIndex].disabled)break;}el.dispatchEvent(new Event('change',{bubbles:true}));return;}accessibleMenuMove(dx,dy);};
const accessibleHint=menuHintText;menuHintText=()=>accessibleHint()+(!['inventory','gems','skills','stash'].includes(menuSurface)?' · L/R：全項目を順送り':'');
const foundryScroll=menuScroll;menuScroll=(stick,dt)=>{if(menuSurface==='skillForge'&&document.activeElement?.closest?.('#foundryGrid,#foundryDetail')){let pane=document.activeElement.closest('#foundryGrid,#foundryDetail');pane.scrollTop+=stick.y*500*dt;return;}foundryScroll(stick,dt);};
const foundryReveal=menuReveal;menuReveal=el=>{let pane=el?.closest?.('#foundryGrid,#foundryDetail');if(pane){menuRevealWithin(pane,el);foundryReveal(pane);}else foundryReveal(el);};
